enum class SgType { TOGGLE, SLIDER, ACTION, GATED, INFO }

/** One settings page (Gboard ki 13 + MgBoard ka Developer/Debug). */
data class SgPage(
    val id: String,
    val en: String,
    val hi: String,
    val icon: String,
)

/**
 * One settings row.
 *
 * @param key      SharedPreferences key for a plain boolean toggle (null = custom get/set).
 * @param btn      Static label for ACTION rows (button text).
 * @param gate     Verbatim Gboard reason string shown when a GATED row is tapped.
 * @param min/max/step  SLIDER range (Gboard-exact).
 * @param webFn    The original web get/set/run/dynamic body, kept as a comment-grade
 *                 reference so the Android handler stays faithful to web behaviour.
 */
data class SgItem(
    val id: String,
    val page: String,
    val type: SgType,
    val en: String,
    val hi: String,
    val sumEn: String? = null,
    val sumHi: String? = null,
    val kw: List<String> = emptyList(),
    val key: String? = null,
    val btn: String? = null,
    val gate: String? = null,
    val min: Double = 0.0,
    val max: Double = 1.0,
    val step: Double = 1.0,
    val webFn: String? = null,
)

