    fun byId(id: String): SgItem? = ALL.firstOrNull { it.id == id }

    fun ofPage(pageId: String): List<SgItem> = ALL.filter { it.page == pageId }

    /**
     * Gboard-exact search: case-insensitive substring over
     * en + hi + sumEn + sumHi + id + keywords (web sgMatches() ka 1:1 port).
     */
    fun matches(it: SgItem, qRaw: String): Boolean {
        val q = qRaw.lowercase()
        if (q.isEmpty()) return false
        val hay = listOfNotNull(it.en, it.hi, it.sumEn, it.sumHi, it.id)
            .plus(it.kw)
            .joinToString(" ")
            .lowercase()
        return hay.contains(q)
    }

    fun search(q: String): List<SgItem> = ALL.filter { matches(it, q) }

